193	
194	        try {
195	            // OrderBid 조회
196	            OrderBid orderBid = orderBidQueryService.findByOrderId(orderId)
197	                    .orElseThrow(() -> new IllegalArgumentException("OrderBid가 존재하지 않습니다. orderId=" + orderId));
198	
199	            Order order = orderBid.getOrder();
200	            log.debug("주문 정보 조회: orderId={}, userId={}, currentStatus={}",
201	                    order.getId(), order.getUser().getId(), order.getStatus());
202	
203	            // 주문 상태를 COMPLETED로 변경
204	            order.updateStatus(OrderStatus.COMPLETED);
205	            log.info("주문 상태 COMPLETED로 변경: orderId={}", orderId);
206	
207	            // 판매 상태 변경 로직
