244	     */
245	    @Override
246	    public OrderShipment process(OrderShipment orderShipment) throws Exception {
247	        String trackingNumber = orderShipment.getTrackingNumber();
248	        Long shipmentId = orderShipment.getId();
249	
250	        if (trackingNumber == null || trackingNumber.isBlank()) {
251	            log.warn("유효하지 않은 운송장 번호: shipmentId={}", shipmentId);
252	            throw new ShipmentException(ShipmentErrorCode.TRACKING_NUMBER_INVALID);
253	        }
254	
255	        log.info("배송 상태 처리 시작: shipmentId={}, trackingNumber={}, currentStatus={}",
256	                shipmentId, trackingNumber, orderShipment.getStatus());
257	
258	        Page page = null;
259	        try {
260	            // browserManager를 통해 페이지 생성
