310	                orderShipment.updateStatus(ShipmentStatus.OUT_FOR_DELIVERY);
311	
312	            } else {
313	                log.info("배송 중 상태 업데이트: shipmentId={}", shipmentId);
314	                orderShipment.updateStatus(ShipmentStatus.IN_TRANSIT);
315	            }
316	
317	            log.info("배송 상태 처리 완료: shipmentId={}, newStatus={}",
318	                    shipmentId, orderShipment.getStatus());
319	
320	            return orderShipment;
321	
322	        } catch (Exception e) {
323	            log.error("배송 상태 처리 중 오류 발생: shipmentId={}, trackingNumber={}, error={}",
324	                    shipmentId, trackingNumber, e.getMessage(), e);
325	
326	            // ShipmentException 타입이 아닌 경우 래핑
