500	     * 1) Reader: 상태가 IN_TRANSIT 또는 OUT_FOR_DELIVERY 인 OrderShipment 목록을 페이지 단위로 읽음
501	     */
502	    @Bean
503	    @StepScope
504	    public JpaPagingItemReader<OrderShipment> shipmentItemReader() {
505	        log.debug("배송 상태 업데이트 ItemReader 구성");
506	        return new JpaPagingItemReaderBuilder<OrderShipment>()
507	                .name("shipmentItemReader")
508	                .entityManagerFactory(entityManagerFactory)
509	                .pageSize(CHUNK_SIZE)
510	                .queryString("SELECT s FROM OrderShipment s WHERE s.status IN ('IN_TRANSIT','OUT_FOR_DELIVERY') AND s.trackingNumber IS NOT NULL")
511	                .build();
