514	    /**
515	     * 2) Processor: 각 OrderShipment에 대해 CJ대한통운 페이지를 조회하여 상태 갱신
516	     *    - parseCjLogisticsStatus(...) 를 통해 배송 상태 파싱
517	     *    - DELIVERY 완료 시 알림, Order 상태 완료 등도 여기서 처리 가능
518	     */
519	    @Bean
520	    @StepScope
521	    public ItemProcessor<OrderShipment, OrderShipment> shipmentItemProcessor() {
522	        log.debug("배송 상태 업데이트 ItemProcessor 구성");
523	
524	        // 만약 Processor를 여러 단계로 나누고 싶다면 CompositeItemProcessorBuilder 사용도 가능
525	        return orderShipment -> {
526	            String trackingNumber = orderShipment.getTrackingNumber();
527	            Long shipmentId = orderShipment.getId();
528	
529	            if (trackingNumber == null || trackingNumber.isBlank()) {
530	                log.warn("유효하지 않은 운송장 번호: shipmentId={}", shipmentId);
531	                throw new ShipmentException(ShipmentErrorCode.TRACKING_NUMBER_INVALID);
532	            }
533	
534	            log.info("배송 상태 조회 시작: shipmentId={}, trackingNumber={}, currentStatus={}",
535	                    shipmentId, trackingNumber, orderShipment.getStatus());
536	
537	            try {
538	                // 2-1) 현재 상태 가져오기
539	                String currentStatus = cjTrackingPlaywright.getCurrentTrackingStatus(trackingNumber);
540	                log.debug("배송 상태 조회 결과: shipmentId={}, currentStatus={}", shipmentId, currentStatus);
541	
542	                // 2-2) 매핑
543	                ShipmentStatus newStatus = mapToShipmentStatus(currentStatus);
544	                log.debug("배송 상태 매핑 결과: currentStatus={}, mappedStatus={}", currentStatus, newStatus);
545	
546	                // 현재 상태와 동일한 경우 중복 처리 방지
547	                if (orderShipment.getStatus() == newStatus) {
548	                    log.debug("상태 변경 없음 (중복 처리 방지): shipmentId={}, status={}",
549	                            shipmentId, newStatus);
550	                    return orderShipment;
551	                }
552	
553	                // 2-3) 상태에 따른 처리
554	                if (newStatus == ShipmentStatus.DELIVERED) {
555	                    log.info("배송 완료 처리: shipmentId={}, orderId={}",
556	                            shipmentId, orderShipment.getOrder().getId());
557	
558	                    orderShipment.updateStatus(ShipmentStatus.DELIVERED);
559	                    // Order 상태도 COMPLETED 로 변경
560	                    orderService.completeOrder(orderShipment.getOrder().getId());
561	                    // 알림 발송
562	                    notificationService.notifyShipmentCompleted(orderShipment.getOrder());
563	                }
564	                else if (newStatus == ShipmentStatus.OUT_FOR_DELIVERY) {
565	                    log.info("배송 출발 처리: shipmentId={}", shipmentId);
566	                    orderShipment.updateStatus(ShipmentStatus.OUT_FOR_DELIVERY);
567	                    // 필요시 알림, 로직 추가
568	                }
569	                else {
570	                    log.info("배송 중 상태 업데이트: shipmentId={}", shipmentId);
571	                    orderShipment.updateStatus(ShipmentStatus.IN_TRANSIT);
572	                }
573	
574	                log.info("배송 상태 처리 완료: shipmentId={}, newStatus={}", shipmentId, orderShipment.getStatus());
575	                return orderShipment; // Writer로 넘김
576	
577	            } catch (Exception e) {
578	                log.error("배송 상태 처리 중 오류 발생: shipmentId={}, trackingNumber={}, error={}",
579	                        shipmentId, trackingNumber, e.getMessage(), e);
580	
581	                // ShipmentException 타입이 아닌 경우 래핑
582	                if (!(e instanceof ShipmentException)) {
583	                    throw new ShipmentException(
584	                            ShipmentErrorCode.EXTERNAL_TRACKING_SERVICE_ERROR,
585	                            "배송 상태 조회 중 오류 발생: " + e.getMessage(),
586	                            e
587	                    );
588	                }
589	                throw e;
590	            }
591	        };
592	    }
