601	    private String parseCjLogisticsStatus(String trackingNumber) throws Exception {
602	        log.debug("운송장 조회 시작 (Jsoup): trackingNumber={}", trackingNumber);
603	
604	        try {
605	            // 예시: 로직 단순화
606	            String url = "https://trace.cjlogistics.com/next/tracking.html?wblNo=" + trackingNumber;
607	            Document doc = Jsoup.connect(url).get();
608	            // tbody#statusDetail 의 마지막 tr => 5번째 td
609	            Elements rows = doc.select("tbody#statusDetail tr");
610	            if (rows.isEmpty()) {
611	                log.warn("배송 정보가 없음: trackingNumber={}", trackingNumber);
612	                throw new ShipmentException(
613	                        ShipmentErrorCode.TRACKING_HTML_PARSE_ERROR,
614	                        "배송 정보가 없습니다. trackingNo=" + trackingNumber
615	                );
616	            }
617	
618	            String status = rows.last().select("td").get(4).text();
619	            log.debug("운송장 조회 완료: trackingNumber={}, status={}", trackingNumber, status);
620	            return status;
621	
622	        } catch (Exception e) {
623	            log.error("운송장 조회 실패: trackingNumber={}, error={}", trackingNumber, e.getMessage(), e);
624	
625	            if (e instanceof ShipmentException) {
626	                throw e;
627	            }
628	
629	            throw new ShipmentException(
630	                    ShipmentErrorCode.TRACKING_HTML_PARSE_ERROR,
631	                    "배송 정보 조회 중 오류 발생: " + e.getMessage(),
632	                    e
633	            );
634	        }
635	    }
