    28	    private static final String TRACKING_URL_PREFIX = "https://trace.cjlogistics.com/next/tracking.html?wblNo=";
    29	    private static final String STATUS_SELECTOR = "tbody#statusDetail tr";
    30	    private static final int TIMEOUT_MS = 30000; // 30초
    31	
    32	    /**
    33	     * 배송 상태 처리기 생성자
    34	     *
    35	     * @param browserManager Playwright 브라우저 관리자
    36	     * @param notificationService 알림 서비스
    37	     * @param orderService 주문 서비스
    38	     */
    39	    public ShipmentItemProcessor(
    40	            PlaywrightBrowserManager browserManager,
    41	            NotificationCommandService notificationService,
    42	            OrderShipmentCommandService orderService
    43	    ) {
    44	        this.browserManager = browserManager;
    45	        this.notificationService = notificationService;
    46	        this.orderService = orderService;
    47	    }
    48	
    49	    /**
    50	     * 주문 배송의 상태를 외부 서비스를 통해 조회하고 업데이트합니다.
    51	     *
    52	     * @param orderShipment 처리할 배송 정보
    53	     * @return 업데이트된 배송 정보
    54	     * @throws Exception 처리 중 오류 발생 시
    55	     */
    56	    @Override
    57	    public OrderShipment process(OrderShipment orderShipment) throws Exception {
    58	        String trackingNumber = orderShipment.getTrackingNumber();
    59	        Long shipmentId = orderShipment.getId();
    60	
    61	        if (trackingNumber == null || trackingNumber.isBlank()) {
    62	            log.warn("유효하지 않은 운송장 번호: shipmentId={}", shipmentId);
    63	            throw new ShipmentException(ShipmentErrorCode.TRACKING_NUMBER_INVALID);
    64	        }
    65	
    66	        log.info("배송 상태 처리 시작: shipmentId={}, trackingNumber={}, currentStatus={}",
    67	                shipmentId, trackingNumber, orderShipment.getStatus());
    68	
    69	        Page page = null;
    70	        try {
    71	            // browserManager를 통해 페이지 생성
    72	            page = browserManager.newPage();
    73	            if (page == null) {
    74	                throw new ShipmentException(ShipmentErrorCode.BROWSER_INITIALIZATION_ERROR);
    75	            }
    76	
    77	            // 타임아웃 설정
    78	            page.setDefaultTimeout(TIMEOUT_MS);
    79	
    80	            // 배송 추적 URL로 이동
    81	            String url = TRACKING_URL_PREFIX + trackingNumber;
    82	            log.debug("배송 조회 페이지로 이동: {}", url);
    83	            page.navigate(url);
    84	
    85	            // 배송 상태 테이블 로드 대기
    86	            log.debug("배송 상태 테이블 로드 대기");
    87	            page.waitForSelector(STATUS_SELECTOR);
    88	
    89	            // 최종 HTML 가져오기
    90	            String renderedHtml = page.content();
    91	            log.debug("페이지 HTML 로드 완료 (길이: {})", renderedHtml.length());
    92	
    93	            // HTML 파싱하여 배송 상태 추출
    94	            String statusText = parseStatusFromHtml(renderedHtml, trackingNumber);
    95	            ShipmentStatus newStatus = mapToShipmentStatus(statusText);
    96	
    97	            log.debug("배송 상태 조회 결과: shipmentId={}, statusText={}, mappedStatus={}",
    98	                    shipmentId, statusText, newStatus);
    99	
   100	            // 현재 상태와 동일한 경우 중복 처리 방지
   101	            if (orderShipment.getStatus() == newStatus) {
   102	                log.debug("상태 변경 없음 (중복 처리 방지): shipmentId={}, status={}",
   103	                        shipmentId, newStatus);
   104	                return orderShipment;
   105	            }
   106	
   107	            // 상태에 따른 처리
   108	            if (newStatus == ShipmentStatus.DELIVERED) {
   109	                log.info("배송 완료 처리: shipmentId={}, orderId={}",
   110	                        shipmentId, orderShipment.getOrder().getId());
   111	
   112	                // 배송 상태 업데이트
   113	                orderShipment.updateStatus(ShipmentStatus.DELIVERED);
   114	
   115	                // 주문 완료 처리 및 알림
   116	                orderService.completeOrder(orderShipment.getOrder().getId());
   117	                notificationService.notifyShipmentCompleted(orderShipment.getOrder());
   118	
   119	            } else if (newStatus == ShipmentStatus.OUT_FOR_DELIVERY) {
   120	                log.info("배송 출발 처리: shipmentId={}", shipmentId);
   121	                orderShipment.updateStatus(ShipmentStatus.OUT_FOR_DELIVERY);
   122	
   123	            } else {
   124	                log.info("배송 중 상태 업데이트: shipmentId={}", shipmentId);
   125	                orderShipment.updateStatus(ShipmentStatus.IN_TRANSIT);
   126	            }
   127	
   128	            log.info("배송 상태 처리 완료: shipmentId={}, newStatus={}",
   129	                    shipmentId, orderShipment.getStatus());
   130	
   131	            return orderShipment;
   132	
   133	        } catch (Exception e) {
   134	            log.error("배송 상태 처리 중 오류 발생: shipmentId={}, trackingNumber={}, error={}",
   135	                    shipmentId, trackingNumber, e.getMessage(), e);
   136	
   137	            // ShipmentException 타입이 아닌 경우 래핑
   138	            if (!(e instanceof ShipmentException)) {
   139	                throw new ShipmentException(
   140	                        ShipmentErrorCode.EXTERNAL_TRACKING_SERVICE_ERROR,
   141	                        "배송 상태 조회 중 오류 발생: " + e.getMessage(),
   142	                        e
   143	                );
   144	            }
   145	            throw e;
   146	        } finally {
   147	            // 페이지 리소스 해제
   148	            if (page != null) {
   149	                try {
   150	                    page.close();
   151	                    log.debug("페이지 리소스 해제 완료");
   152	                } catch (Exception e) {
   153	                    log.warn("페이지 닫기 실패: {}", e.getMessage());
   154	                }
   155	            }
   156	        }
   157	    }
